import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'min': 5.0, 'span': 2.0, 'ratio': 0.75})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 3, 'min': 4.0, 'span': 10.0, 'ratio': 0.75})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'min': 2.0, 'span': 10.0, 'ratio': 0.75})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'min': 0, 'span': 0, 'ratio': 0.0})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'min': 5.0, 'span': 11.0, 'ratio': 0.75})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'min': 4.0, 'span': 0.0, 'ratio': 0.25})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'min': 10.0, 'span': 0.0, 'ratio': 1.0})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 2, 'min': 6.0, 'span': 38.0, 'ratio': 0.5})

if __name__ == '__main__':
    unittest.main()
